function stepShot(s,dt){const steps=Math.max(1,Math.ceil(Math.hypot(s.vx,s.vy)*dt/3)),step=dt/steps;for(let i=0;i<steps&&s.life>0;i++){const ox=s.x,oy=s.y;s.x+=s.vx*step;s.y+=s.vy*step;s.life-=step;if(mode===2){if(s.x<23||s.x>457){s.vx*=-1;s.x=clamp(s.x,23,457);bounce(s)}if(s.life>0&&(s.y<23||s.y>247)){s.vy*=-1;s.y=clamp(s.y,23,247);bounce(s)}if(s.life<=0)continue;for(const b of obstacles){if(b.dead||s.x<b.x-1||s.x>b.x+b.w+1||s.y<b.y-1||s.y>b.y+b.h+1)continue;if(b.kind==='crate'){b.hp--;s.life=0;b.flash=.1;if(b.hp<=0){b.dead=true;score+=25;burst(b.x+b.w/2,b.y+b.h/2)}break}if(ox<b.x||ox>b.x+b.w){s.vx*=-1;s.x=ox}else{s.vy*=-1;s.y=oy}bounce(s);break}if(s.life<=0)continue;for(const t of targets)if(!t.dead&&Math.hypot(t.x-s.x,t.y-s.y)<10){s.life=0;if(!t.bank||s.bounces>0){t.dead=true;score+=100+Math.min(s.bounces,5)*25;burst(t.x,t.y)}else{t.flash=.2;tone(140)}break}}else{if(mode===1&&scaffolds.some(b=>s.x>b.x&&s.x<b.x+b.w&&s.y>b.y&&s.y<b.y+b.h)){s.life=0;continue}for(const e of enemies)if(!e.dead&&(e.solid?lightParts(e).some(b=>overlap({x:s.x-2,y:s.y-2,w:4,h:4},b)):overlap({x:s.x-2,y:s.y-2,w:4,h:4},bounds(e)))){hitEnemy(e,s);break}}}}
function update(dt){time+=dt;cool-=dt;spawn-=dt;trafficSpawn-=dt;invul-=dt;damageFlash-=dt;const dx=(keys.ArrowRight||keys.KeyD?1:0)-(keys.ArrowLeft||keys.KeyA?1:0),dy=(keys.ArrowDown||keys.KeyS?1:0)-(keys.ArrowUp||keys.KeyW?1:0);if(mode!==2)movePlayer(dx,dy,dt);else{angle+=dx*dt*(keys.ShiftLeft?.65:1.8);levelTime+=dt;for(const b of obstacles){if(b.amp)b.y=b.baseY+Math.sin(levelTime*b.speed)*b.amp;b.flash=Math.max(0,(b.flash||0)-dt)}for(const t of targets)t.flash=Math.max(0,(t.flash||0)-dt);if(levelTime>=LEVELS[levelIndex].limit){finish(false);return}}
if(cool<=0&&(mode===2?shotQueued:keys.Space)){shotQueued=false;if(fire())cool=mode===2?.23:mode===0?BALANCE.sky.laserCooldown:.16}
if(mode<2&&spawn<=0){if(mode===0){const d=skyDifficulty();spawn=d.enemyInterval;const pool=skyPool();const e=skyEnemy(pool[Math.floor(Math.random()*pool.length)]);if(time<10&&e.type==='hawk')e.y=120;enemies.push(e)}else{const d=peakDifficulty();spawn=d.spawnInterval;const pool=peakPool();enemies.push(falling(pool[Math.floor(Math.random()*pool.length)]))}}
if(mode===0){for(const type of ['cat','kid','highCat'])if(time>=BALANCE.sky.introduce[type]&&!introduced.has(type)){introduced.add(type);enemies.push(skyEnemy(type))}duckSpawn-=dt;if(duckSpawn<=0){enemies.push(skyEnemy('duck'));duckSpawn=28}signSpawn-=dt;if(signSpawn<=0){signSpawn=spawnSkySolid('overpass')?22:1}falconSpawn-=dt;if(falconSpawn<=0){enemies.push(skyEnemy('falcon'));falconSpawn=14}streetlightSpawn-=dt;if(streetlightSpawn<=0){streetlightSpawn=spawnSkySolid('streetlight')?16-3*skyDifficulty().d:1}planeSpawn-=dt;if(trafficSpawn<=0){trafficSpawn=skyDifficulty().trafficInterval;const traffic=time<12?['taxi']:time<21?['taxi','motorcycle']:['taxi','motorcycle','truck'];enemies.push(vehicle(traffic[Math.floor(time/3)%traffic.length]))}if(planeSpawn<=0){enemies.push(skyEnemy('plane'));planeSpawn=skyDifficulty().planeInterval}}
updateEnemies(dt);if(mode===0)resolveStreetlights();for(const s of shots)stepShot(s,dt);
if(mode<2)for(const e of enemies)if(!e.dead&&!e.harmless&&invul<=0&&overlap(playerBox(),bounds(e))){lives--;invul=1.5;damageFlash=.15;burst(player.x,player.y);if(e.type==='paint'||e.type==='planeShot'||e.type==='icicle'||e.type==='shard')e.dead=true;if(lives<=0){finish(false);return}}
shots=shots.filter(s=>s.life>0&&s.x>-10&&s.x<490&&s.y>-15&&s.y<285);enemies=enemies.filter(e=>!e.dead&&e.x>-90&&e.x<620&&e.y>-70&&e.y<310);targets=targets.filter(t=>!t.dead);obstacles=obstacles.filter(b=>!b.dead);particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);if(mode===2&&shotsLeft===0&&shots.length===0&&targets.length>0){lossReason='ammo';finish(false);return}if(mode===1)score=Math.floor(climb);if(mode===1&&climb>=1000||mode===2&&targets.length===0){finish(true);return}hud()}
function hpBar(x,y,hp,max){if(!Number.isFinite(hp)||max<2)return;for(let i=0;i<max;i++)rect(ctx,x-max*2+i*4,y,3,2,i<hp?3:1)}
function draw(){scene(ctx,480,270,state==='ready'?0:time,mode);if(mode===1)for(const b of scaffolds)Art.draw(ctx,'scaffold',b.x,b.y,{width:b.w,height:b.h});if(mode===2){for(const b of obstacles){ctx.globalAlpha=b.flash?.5:1;Art.draw(ctx,b.kind,b.x,b.y,{width:b.w,height:b.h,time});ctx.globalAlpha=1;if(b.kind==='crate')hpBar(b.x+b.w/2,b.y-5,b.hp,b.maxHp)}for(const t of targets){Art.draw(ctx,'target',t.x,t.y);if(t.bank){ctx.strokeStyle=C[t.flash?0:3];ctx.lineWidth=1;ctx.beginPath();ctx.arc(t.x,t.y,12,0,Math.PI*2);ctx.stroke()}}const p=eye();ctx.strokeStyle=C[2];ctx.setLineDash([2,4]);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+Math.cos(angle)*64,p.y+Math.sin(angle)*64);ctx.stroke();ctx.setLineDash([])}for(const e of enemies){if(e.warning>0){Art.draw(ctx,'falconWarning',449,20,{time});continue}ctx.globalAlpha=e.flash?.5:1;Art.draw(ctx,e.type,e.x,e.y,{time,aim:e.aim});ctx.globalAlpha=1;hpBar(e.x,e.y-e.h/2-5,e.hp,e.maxHp)}for(const s of shots){ctx.strokeStyle=C[3];ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x,s.y);const n=Math.hypot(s.vx,s.vy);ctx.lineTo(s.x-s.vx/n*8,s.y-s.vy/n*8);ctx.stroke()}particles.forEach(p=>rect(ctx,p.x,p.y,2,2,3));if(invul<=0||Math.floor(invul*12)%2===0)Art.draw(ctx,'pigeon',player.x,player.y,{time,flap:Math.floor(time*8)%2,firing:cool>.1});if(state==='ready'&&mode===0){Art.draw(ctx,'taxi',330,BALANCE.sky.roadY+24);Art.draw(ctx,'truck',425,BALANCE.sky.roadY+24);Art.draw(ctx,'highCat',210,BALANCE.sky.roadY-13);Art.draw(ctx,'plane',380,32);Art.draw(ctx,'streetlight',280,BALANCE.sky.roadY)}if(damageFlash>0){ctx.fillStyle='#ffffff55';ctx.fillRect(0,0,480,270)}}
function frame(ts){const dt=Math.min((ts-last)/1000,.04);last=ts;if(state==='playing')update(dt);draw();requestAnimationFrame(frame)}
$('#start').onclick=start;$('#pause').onclick=pause;$('#reset').onclick=()=>{state='ready';start()};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'SOUND ON ♪':'SOUND OFF ♪';$('#sound').setAttribute('aria-pressed',sound);tone()};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>select(+b.dataset.mode));document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{levelIndex=+b.dataset.level;select(2)});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)&&!['BUTTON','A'].includes(e.target.tagName))e.preventDefault();if(e.code==='Enter'&&!e.repeat&&e.target.tagName!=='BUTTON'&&state!=='playing')start();else {if(e.code==='Space'&&mode===2&&!e.repeat&&!keys.Space)shotQueued=true;keys[e.code]=true;}if(e.code==='KeyP'&&!e.repeat)pause()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};if(state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause();updateFact()});document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.key==='Space'&&mode===2&&!keys.Space)shotQueued=true;keys[b.dataset.key]=true};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys[b.dataset.key]=false});
const FACTS=[
 ['Both pigeon parents make “crop milk” to feed their chicks. A very unexpected family recipe.','https://www.allaboutbirds.org/guide/Rock_Pigeon/lifehistory'],
 ['Pigeons served as military messengers in both World Wars. Tiny couriers, enormous responsibility.','https://www.allaboutbirds.org/guide/Rock_Pigeon/overview'],
 ['Pigeons have lived alongside people for more than 5,000 years. They were city regulars before cities were cool.','https://www.allaboutbirds.org/guide/Rock_Pigeon/overview'],
 ['A pigeon can use the sun’s position to help navigate. Built-in directions, no phone required.','https://www.allaboutbirds.org/guide/Rock_Pigeon/overview'],
 ['“Rock dove” and “homing pigeon” are other names for the rock pigeon. A bird of many business cards.','https://portal.ct.gov/deep/wildlife/fact-sheets/rock-pigeon'],
 ['Pigeon plumage can be almost entirely white. The classic gray suit is optional.','https://www.allaboutbirds.org/guide/Rock_Pigeon/id'],
 ['Pigeons sometimes reuse a nest site and keep adding to it. Home improvement, pigeon edition.','https://www.audubon.org/field-guide/bird/rock-pigeon'],
 ['Pigeons can breed throughout the year. Their family calendar stays busy.','https://portal.ct.gov/deep/wildlife/fact-sheets/rock-pigeon']];
function updateFact(now=Date.now()){const hour=Math.floor(now/3600000),fact=FACTS[((hour%FACTS.length)+FACTS.length)%FACTS.length];$('#pigeonFact').textContent=fact[0];$('#factSource').href=fact[1];$('#factNext').textContent='NEXT FACT AT '+new Date((hour+1)*3600000).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}
updateFact();setInterval(updateFact,15000);
document.querySelectorAll('[data-art]').forEach(c=>{const g=c.getContext('2d'),m=+c.dataset.art;scene(g,240,100,0,m);Art.draw(g,'pigeon',50,45,{flap:true});if(m===0){Art.draw(g,'taxi',150,77);Art.draw(g,'cat',200,45)}else if(m===1){Art.draw(g,'scaffold',95,35,{width:115,height:8});Art.draw(g,'icicle',145,14);Art.draw(g,'tv',195,80)}else{Art.draw(g,'target',190,40);Art.draw(g,'wall',110,30,{width:14,height:50})}});select(0);requestAnimationFrame(frame);
